def add_roles_table():
    """Таблица 1.1: в колонке роли — все функции, доступные этой роли."""
    columns = [
        SHARED + GUEST_ONLY,
        SHARED + USER_ONLY,
        SHARED + USER_ONLY + ADMIN_ONLY,
    ]
    height = max(len(c) for c in columns)
    table = doc.add_table(rows=height + 1, cols=3)
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    for j, title in enumerate(["Гость", "Авторизованный пользователь", "Администратор"]):
        set_cell(table.cell(0, j), title, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
    repeat_header_row(table.rows[0])
    for j, column in enumerate(columns):
        for i in range(height):
            # короткие колонки внизу остаются пустыми, как в образце
            text = column[i] if i < len(column) else ""
            set_cell(table.cell(i + 1, j), text)
    for row in table.rows:
        for cell in row.cells:
            cell.width = Cm(5.5)


